function beep(type='click'){if(!sound)return;try{const ctx=new(window.AudioContext||window.webkitAudioContext)(),o=ctx.createOscillator(),v=ctx.createGain();o.connect(v);v.connect(ctx.destination);o.frequency.setValueAtTime(type==='win'?660:220,ctx.currentTime);o.frequency.exponentialRampToValueAtTime(type==='win'?990:110,ctx.currentTime+.16);v.gain.setValueAtTime(.045,ctx.currentTime);v.gain.exponentialRampToValueAtTime(.001,ctx.currentTime+.24);o.start();o.stop(ctx.currentTime+.25);o.onended=()=>ctx.close()}catch{}}
function toast(text){$('#toast').textContent=text;$('#toast').classList.add('show');clearTimeout(timer);timer=setTimeout(()=>$('#toast').classList.remove('show'),3300)}
function modal(html,actor=null){modalActor=actor??(g?(reactingPlayer(g)??g.turn):null);hideInspection();$('#modal-root').innerHTML=`<div class="overlay"><section class="modal" role="dialog" aria-modal="true">${html}</section></div>`;$('#modal-root').querySelector('button')?.focus({preventScroll:true})}
function close(){pendingBotDecision=null;modalActor=null;$('#modal-root').innerHTML='';net?.sync()}
