 return `<article class="log event-${type} ${i===0?'latest-event':''}"><span class="event-icon">${l.icon||style.icon}</span><div class="event-body"><div class="event-meta"><strong>${esc(l.title||style.title)}</strong><small>${l.round?'РАУНД '+l.round:'НАЧАЛО'}${l.sequence?' · #'+l.sequence:''}</small></div>${actor?`<span class="event-actor" style="--actor-color:${colors[l.actor]}">${p.bot?'♟':'●'} ${esc(actor)}${p.bot?' · соперник':''}</span>`:''}<p>${esc(l.text)}</p>${l.card?`<div class="event-card">${cardArt(l.card)}<span>${esc(l.card.name)}</span></div>`:''}</div></article>`;
