function setButton(s){const cards=CARDS.filter(c=>c.set===s.id);return `<div class="set-row" data-set-search="${esc([s.name,s.sub,...cards.flatMap(c=>[c.name,c.en])].join(' ').toLowerCase())}"><button class="set ${selected.includes(s.id)?'selected':''}" data-set="${s.id}" aria-pressed="${selected.includes(s.id)}" ${s.id==='base'?'aria-disabled="true"':''}><span class="set-icon ${s.color}">${s.icon}</span><span><strong>${esc(s.name)}</strong><small>${esc(s.sub)} · ${cards.length} ${plural(cards.length,['карта','карты','карт'])}</small></span><span class="check">${selected.includes(s.id)?'✓':'+'}</span></button></div>`}
