async function executeBotAction(action){const p=g.players[g.turn];if(action.type==='hireling'||action.type==='force-help'){const r=action.type==='hireling'?assignHireling(g,g.turn,action.id):forceHelper(g,g.turn,action.target);if(r.ok)log(`${p.name}: ${r.text}`);return r.ok}if(action.type==='monster-action'){const r=playMonsterAction(g,g.turn,action.id);if(r.ok&&r.text)log(r.text);return r.ok}if(action.type==='equip'){const c=p.hand.find(c=>c.uid===action.uid);const r=c&&equip(p,c,action.replaceUid);if(r?.ok)log(`${p.name} надевает ${c.name}.`);return !!r?.ok}
if(action.type==='play'||action.type==='trouble'){play(action.uid,action.target??null);return true}
if(action.type==='ability'){const r=useAbility(g,g.turn,action.key,action);if(r.ok){if(action.key==='steal')g.aiTheftUsed=true;log(r.text);if(r.faceUp)resolveDoor(r.faceUp)}return r.ok}
if(action.type==='special'){const r=playSpecialCard(g,g.turn,action.uid,action);if(r.ok)log(r.text);return r.ok}if(action.type==='treasure'){const r=useTreasure(g,g.turn,action.uid,action.targetUid);if(r.ok)log(r.text);return r.ok}
if(action.type==='sell'){const c=p.hand.find(c=>c.uid===action.uid),r=sellItem(g,g.turn,action.uid);if(r.ok)log(`${p.name} продаёт «${c.name}» за ${r.gold} золотых${r.levels?` и получает ${r.levels} ур.`:''}.`);return r.ok}
if(action.type==='help'){const h=g.players[action.target];g.helpUsed=true;let yes=h.bot?willingToHelp(g,action.target):await new Promise(resolve=>{pendingBotDecision={actor:action.target,run:()=>{const yes=willingToHelp(g,action.target);close();resolve(yes)}};actorModal(action.target,`<div class="eyebrow">ПРЕДЛОЖЕНИЕ ПОМОЩИ</div><h2>${esc(p.name)} зовёт ${esc(h.name)}</h2><p>Одно сокровище за помощь. Твоя сила ${power(h)}, монстры ${monsterPower(g)}. При неудаче придётся смываться.</p><button class="primary" id="accept-bot-help">Помогу за сокровище</button><button class="outline" id="decline-bot-help">Справляйся сам</button>`);$('#accept-bot-help').onclick=()=>{close();resolve(true)};$('#decline-bot-help').onclick=()=>{close();resolve(false)}});if(yes){g.helper=action.target;if(g.illusionBonus){dropIllusion(g)}log(`${h.name} помогает ${p.name} за сокровище.`)}else log(`${h.name} отказал в помощи.`);return true}
if(action.type==='fight'||action.type==='run'){await requestResolution(action.type);return true}
if(['door','loot'].includes(action.type)){busy=false;act(action.type);busy=true;return true}return false}
async function runBots(){const mine=++token;busy=true;const wait=()=>new Promise(r=>setTimeout(r,550));while(mine===token&&g.players[g.turn].bot&&g.winner===null){let steps=0;while(g.players[g.turn].bot&&g.phase!=='done'&&g.winner===null&&mine===token&&steps++<70){if(g.pendingDivine||g.pendingEncounter)await handlePending();if(g.pendingCurse)await waitForCurse();const action=chooseBotAction(g,g.turn,g.phase==='door'?'prepare':g.phase);const ok=await executeBotAction(action);if(mine!==token||!g)return;if(g.pendingDivine||g.pendingEncounter)await handlePending();if(g.pendingCurse)await waitForCurse();if(!ok){if(g.phase==='combat')await requestResolution('run');else if(g.phase==='loot'){busy=false;act('loot');busy=true}else{busy=false;act('door');busy=true}}render();await wait()}if(mine!==token)return;if(!g.players[g.turn].bot){busy=false;render();return}if(g.winner!==null)break;if(aftermathPromise)await aftermathPromise;await wait();if(mine!==token)return;const actor=g.players[g.turn];actor.hand.sort((a,b)=>cardKeepValue(actor,b)-cardKeepValue(actor,a));advanceTableTurn();render()}busy=false}
function bot(){if(g?.reaction){driveReactions();return}botScheduler.request()}
function newGame(){if(net?.active){net.roomScreen();return}modal('<h2>Начать новую историю?</h2><p>Текущая партия будет заменена после старта новой.</p><button class="primary" id="confirm-new">К выбору игроков</button><button class="text-btn" id="keep">Остаться за столом</button>');$('#confirm-new').onclick=()=>{close();lobby()};$('#keep').onclick=close}
function celebrate(){for(let i=0;i<40;i++){const e=document.createElement('i');e.className='confetti';e.style.cssText=`left:${Math.random()*100}%;background:${colors[i%5]};animation-delay:${Math.random()}s;transform:rotate(${Math.random()*360}deg)`;document.body.append(e);setTimeout(()=>e.remove(),4500)}}
function openGallery(){let visible=40,paintedOnly=false;modal(`<div class="eyebrow">БЕСТИАРИЙ И БАРАХОЛКА</div><h2>Альбом карт</h2><p>✓ — проверенные правила, ◐ — часть эффектов или параметры подборки. Непроверенные особенности отложены. У каждой карты — подобранная иллюстрация. Один и тот же рисунок сохраняется в руке, бою и снаряжении.</p><div class="gallery-controls"><input id="gallery-search" placeholder="Монстр, предмет, класс…" aria-label="Поиск карт"><select id="gallery-set" aria-label="Набор карт"><option value="all">Все ${SETS.length} набора</option>${SETS.map(s=>`<option value="${s.id}">${esc(s.name)}</option>`).join('')}</select></div><button class="outline" id="painted-only" aria-pressed="false">Карикатуры в игре (${new Set(CARDS.filter(c=>GENERATED_CARD_ART[c.en]).map(c=>c.en)).size})</button><a class="outline" href="base-art.html" target="_blank" rel="noopener">Полный оригинал: ${BASE_ART_CATALOG.ready} / ${BASE_ART_CATALOG.totalUnique} ↗</a><div class="gallery-grid" id="gallery-grid"></div><p id="gallery-count" class="gallery-caption"></p><button class="outline" id="gallery-more">Показать ещё</button><p class="gallery-credits">Оригинальные карикатуры созданы для этой игры. Остальные иллюстрации: <a href="https://game-icons.net" target="_blank" rel="noreferrer">Game-icons.net</a> · <a href="assets/cards/ATTRIBUTION.md" target="_blank">авторы</a> · CC BY 3.0. <a href="data/card-art.json" target="_blank">Источники по картам</a>.</p><button class="text-btn" id="close-gallery">Закрыть альбом</button>`);$('.modal').classList.add('card-gallery');function update(){const q=$('#gallery-search').value.trim().toLowerCase(),set=$('#gallery-set').value,cards=CARDS.filter(c=>(!paintedOnly||GENERATED_CARD_ART[c.en])&&(set==='all'||c.set===set)&&`${c.name} ${c.en}`.toLowerCase().includes(q));$('#gallery-grid').innerHTML=cards.slice(0,visible).map(c=>card(c)).join('');$('#gallery-count').textContent=`Показано ${Math.min(visible,cards.length)} из ${cards.length}`;$('#gallery-more').hidden=visible>=cards.length}$('#painted-only').onclick=()=>{paintedOnly=!paintedOnly;$('#painted-only').setAttribute('aria-pressed',String(paintedOnly));$('#painted-only').classList.toggle('active',paintedOnly);visible=40;update()};$('#gallery-search').oninput=()=>{visible=40;update()};$('#gallery-set').onchange=()=>{visible=40;update()};$('#gallery-more').onclick=()=>{visible+=40;update()};$('#close-gallery').onclick=close;update()}
$('#gallery').onclick=openGallery;
$('#rules').onclick=()=>{modal(`<div class="eyebrow">ПАМЯТКА ПО ПРАВИЛАМ</div><h2>Две колоды. Восемь карт. Ни совести.</h2><ol class="rules-list"><li><b>Подготовка.</b> Двери и сокровища перемешиваются отдельно. Каждый получает 4 двери и 4 сокровища, начинает человеком 1 уровня без класса. Только карты на столе дают способности.</li><li><b>Дверь.</b> Открой верхнюю дверь: монстр начинает бой, проклятие срабатывает сразу, остальное берётся в руку. Если монстра нет, либо сыграй своего, либо возьми ещё одну закрытую дверь.</li><li><b>Бой.</b> Сила — уровень, шмотки, способности и разовые бонусы. Нужен перевес; воин на любой стороне искателей разрешает ничью. Один помощник рискует вместе с тобой. Соперники перед исходом получают окно подставы: Бродячая тварь + монстр, нежить к нежити, усилители, зелья и подрезки.</li><li><b>Способности.</b> Под рукой показаны постоянные эффекты и кнопки активных действий. Стоимость списывается только после выбора нужных карт. Мультиклассы и мультирасы объединяют эффекты разных активных карт. Условия и лимиты указаны в блоке персонажа.</li><li><b>Смывка.</b> От каждого монстра отдельный кубик: нужно 5 с учётом расовых бонусов. Волшебник и хафлинг могут использовать способности после неудачного броска. Смерть сохраняет классы, расы и уровень; новые 4+4 выдаются в начале собственного следующего хода.</li><li><b>Конец хода.</b> Лимит руки 5, у дварфа 6. Излишки поровну идут игрокам с самым низким уровнем. Если ты тоже самый низкий, они сбрасываются. У дверей и сокровищ отдельные сбросы; исчерпанная колода перемешивает только свой сброс.</li><li><b>Победа.</b> Достигни 10 уровня убийством монстра без помощника. С помощником обычная награда повышает максимум до 9-го. Явные исключения карт сохраняются. Эльф получает по уровню за каждого монстра, убитого с его помощью, и так тоже может выиграть. Зачарование и приручение уровней не дают.</li></ol><p class="muted">Это адаптация подборок карт. Возврат снаряжения в руку, накопление золотых при продаже и часть редких эффектов упрощены. У проверенных предметов учтены цена, размер и ограничения; у исходных монстров — индивидуальные непотребства и условия боя. Не реализованы все дополнительные способности каждой печатной карты; блок персонажа перечисляет работающие.</p><p><a href="https://munchkin.game/site-munchkin/assets/files/1138/munchkin_rules-1.pdf" target="_blank" rel="noreferrer">Правила издателя</a> · <a href="https://munchkin.game/gameplay/faq/" target="_blank" rel="noreferrer">Официальные разъяснения</a></p><button class="primary" id="close-rules">Я всё понял. Наверное.</button>`);$('#close-rules').onclick=close};
$('#about').onclick=()=>{modal(`<h2>Фанатская подземка</h2><p>Манчкин принадлежит Steve Jackson Games. Это неофициальная локальная игра, не официальный Munchkin Digital.</p><p>В подборке ${CARDS.length} названий карт из ${SETS.length} наборов классического фэнтезийного Манчкина. Исходные три набора включены по умолчанию. Новые наборы содержат адаптированные подборки, а не полные колоды. Подземелья разыгрываются как события дверей, задания дают дополнительное сокровище, усилители меняют силу монстра. Это не полные колоды. Русские названия — описательные переводы, иллюстрации подобраны из Game-icons; авторы и лицензия указаны ниже. Эффекты и баланс адаптированы, оригинальные тексты и сканы не используются.</p><p>Оригинальные карикатуры созданы для этой игры. Остальные иллюстрации: <a href="https://game-icons.net" target="_blank" rel="noreferrer">Game-icons.net</a> · <a href="assets/cards/ATTRIBUTION.md" target="_blank">авторы</a> · <a href="https://creativecommons.org/licenses/by/3.0/" target="_blank" rel="noreferrer">CC BY 3.0</a>. SVG-файлы не изменены, цвет и оформление добавлены через CSS. <a href="data/card-art.json" target="_blank">Источник каждой иллюстрации</a>.</p><p>Официальные списки названий сохранены в <a href="data/publisher-catalog.json" target="_blank">каталоге источников</a>. Источники: <a href="https://munchkin.game/" target="_blank" rel="noreferrer">Манчкин</a>, <a href="https://munchkin.game/products/games/munchkin/munchkin-2-unnatural-axe/" target="_blank" rel="noreferrer">Unnatural Axe</a>, <a href="https://munchkin.game/products/games/munchkin/munchkin-3-clerical-errors/" target="_blank" rel="noreferrer">Clerical Errors</a>, <a href="https://munchkin.game/gameplay/rules/" target="_blank" rel="noreferrer">правила издателя</a>.</p><button class="primary" id="close-about">Обратно в таверну</button>`);$('#close-about').onclick=close};$('#sound').onclick=()=>{sound=!sound;$('#sound').classList.toggle('enabled',sound);$('#sound').setAttribute('aria-label',sound?'Выключить звук':'Включить звук');beep();toast(sound?'Звуки таверны включены':'Таверна притихла')};$('#home').onclick=e=>{e.preventDefault();if(net?.active){net.session?net.roomScreen():net.showBrowser();return}g?newGame():lobby()};document.addEventListener('keydown',e=>{if(e.key==='Escape')hideInspection();if(e.key==='Escape'&&!busy&&!g?.pendingEncounter&&!g?.pendingDivine&&!g?.pendingCurse&&!$('#ready')&&!$('#reaction-ready')&&!$('#accept-bad')&&!$('#accept-bot-help')&&!$('#confirm-bad-stuff')&&!$('#die-pass'))close()});net=new NetworkLobby({getGame:()=>g,actor:()=>reactingPlayer(g)??g.turn,modalActor:()=>modalActor,card,publicPlayerDetails,onLeave:()=>{token++;botScheduler.reset();g=null;busy=false;close();lobby()},onStart:startNetworkGame,onRestore:restoreNetworkGame,onControls:applyNetworkControls,canControl:canNetworkControl,onSuspend:()=>{token++;botScheduler.reset();busy=false;g=null;close()}});lobby();net.restore();


function askConsent(text){return new Promise(resolve=>{const actor=g.players.findIndex(p=>text.startsWith(p.name));pendingBotDecision={actor,run:()=>{close();resolve(true)}};actorModal(actor>=0?actor:g.turn,`<h2>${esc(text)}</h2><button class="primary" id="consent-yes">Да</button><button class="outline" id="consent-no">Нет</button>`);$('#consent-yes').onclick=()=>{close();resolve(true)};$('#consent-no').onclick=()=>{close();resolve(false)}})}
async function handlePending(){if(pendingTask)return pendingTask;pendingTask=(async()=>{while(g.pendingDivine||g.pendingEncounter){
 if(g.pendingDivine){const d=g.pendingDivine,actor=d.order[d.index],p=g.players[actor],cleric=p.hand.find(c=>c.en==='Cleric');if(!cleric){respondDivine(g,actor);continue}const yes=p.bot||await askConsent(`${p.name}, стать клириком перед Божественным вмешательством и получить уровень?`);respondDivine(g,actor,{clericUid:yes?cleric.uid:null});}
 else{const prompt=encounterPrompt(g);if(!prompt)continue;const uids=await chooseBadStuff({...prompt,exactOptional:prompt.optional,reason:prompt.kind==='lawyers'?'Можно обменять ровно 2 сокровища на 2 новых закрытых, либо отказаться.':'Перед боем сбрось одну шмотку, из руки или игры.'});const r=respondEncounter(g,uids);if(!r.ok)continue;}
 save();}render();})().finally(()=>{pendingTask=null});return pendingTask}
function advancedActionsPanel(p){const actor=g.players.indexOf(p),actions=[...monsterActions(g,actor).map(a=>({id:'monster|'+a.id,name:a.name})),...hirelingOptions(g,actor).map(a=>({id:'hireling|'+a.id,name:a.name})),...kneepadTargets(g,actor).map(a=>({id:'kneepad|'+a.uid,name:'Заставить помочь: '+a.name}))];return actions.length?`<section class="abilities-panel"><h3>Особые действия карт</h3>${actions.map(a=>`<button class="outline" data-extra-action="${a.id}" ${p.bot?'disabled':''}>${esc(a.name)}</button>`).join('')}</section>`:''}
function applyExtraAction(id){const actor=g.players.indexOf(activePlayer()),[kind,key]=id.split('|');const r=kind==='monster'?playMonsterAction(g,actor,key):kind==='hireling'?assignHireling(g,actor,key):forceHelper(g,actor,+key);if(r.ok){if(r.text)log(r.text);render()}else toast('Действие уже недоступно')}
function chooseAfterEscape({actor,fighter,cards,monster,escaped}){const p=g.players[actor];if(p.bot){const own=actor===fighter,ally=actor===g.turn&&fighter===g.helper||actor===g.helper&&fighter===g.turn;return Promise.resolve(!escaped&&own||escaped&&!ally&&!own&&(botProfile(p).spite>.6||g.players[fighter].level>=8)?{uid:cards[0].uid}:null)}return new Promise(resolve=>{pendingBotDecision={actor,run:()=>{const result=chooseAfterEscape(arguments[0]);close();Promise.resolve(result).then(resolve)}};actorModal(actor,`<div class="eyebrow">ПОСЛЕ СМЫВКИ · ${esc(p.name)}</div><h2>${escaped?'Заставить перебросить?':'Спастись невидимостью?'}</h2><p>${esc(g.players[fighter].name)} · ${esc(monster.name)}. ${escaped?'Клей заставит бросить снова, даже после автоматической смывки.':'Зелье спасёт от этого монстра.'}</p>${cards.map(c=>`<button class="outline target" data-escape-after="${c.uid}">${esc(c.name)}</button>`).join('')}<button class="primary" id="escape-after-pass">Пас</button>`);$('#escape-after-pass').onclick=()=>{close();resolve(null)};$$('[data-escape-after]',el=>el.onclick=()=>{close();resolve({uid:+el.dataset.escapeAfter})})})}
